options.afterRender:
const element = context.element;
const theme = context.grafana.theme;

/** Colors follow the dashboard theme, so every panel reads in light and dark. */
const palette = {
  '--pdx-text': theme.colors.text.primary,
  '--pdx-dim': theme.colors.text.secondary,
  '--pdx-link': theme.colors.text.link,
  '--pdx-border': theme.colors.border.weak,
  '--pdx-panel': theme.colors.background.primary,
  '--pdx-phase': theme.colors.background.secondary,
  '--pdx-chip': theme.colors.background.primary,
  '--pdx-ok': theme.colors.success.text,
  '--pdx-bad': theme.colors.error.text,
  '--pdx-warn': theme.colors.warning.text,
  '--pdx-run': theme.colors.primary.text,
  '--pdx-accent': theme.colors.border.strong,
  '--pdx-mono': theme.typography.fontFamilyMonospace,
};
Object.keys(palette).forEach((key) => element.style.setProperty(key, palette[key]));

/**
 * The plugin renders `element` itself and keeps track of what it put there,
 * so replacing those children leaves it patching nodes that are gone and the next
 * refresh throws. `.pdx-mount` comes from the panel's content empty, which leaves
 * the plugin nothing to track inside it.
 */
const mountOf = () => element.querySelector('.pdx-mount') || element;

/** Box the panel scrolls in, walking out from the drawing. null while nothing scrolls. */
const scrollerOf = (node) => {
  for (let box = node; box; box = box.parentElement) {
    if (box.scrollHeight > box.clientHeight + 1 && /auto|scroll/.test(getComputedStyle(box).overflowY)) {
      return box;
    }
  }
  return null;
};

/** Swaps a fresh drawing in, holding the reader's scroll position across the refresh. */
const paint = (root) => {
  const mount = mountOf();
  const scroller = scrollerOf(mount);
  const top = scroller ? scroller.scrollTop : 0;
  mount.replaceChildren(root);
  if (scroller && scroller.scrollTop !== top) {
    scroller.scrollTop = top;
  }
};

/**
 * One color per run, the same on every panel. The key hashes onto a ring of
 * hues, so a merge request keeps its color across pushes and refreshes.
 */
const HUES = [212, 28, 142, 282, 48, 322, 182, 2, 102, 242, 62, 342];
const hueOf = (key) => {
  let hash = 7;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  return HUES[hash % HUES.length];
};
const colorOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 38 : 42) + '%)';
const tintOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 55 : 45) + '% / 0.14)';

/** Short name of a run: the merge request number for a review, the commit for production. */
const nameOf = (row) => {
  const key = row.key || '';
  if (row.kind === 'review' || key.indexOf('!') !== -1) {
    return '!' + (row.iid || key.split('!')[1] || '');
  }
  return row.sha || key;
};

/** Frames arrive one per query. Reading them by refId keeps order out of it. */
const frames = {};
((context.panelData && context.panelData.series) || []).forEach((frame) => {
  frames[frame.refId] = frame;
});

/** Rows of a frame as plain objects, the sample value under `value`. */
const readRows = (refId) => {
  const frame = frames[refId];
  if (!frame || !frame.fields || !frame.length) {
    return [];
  }
  const valueField = frame.fields.find((field) => field.type === 'number' && /^Value/.test(field.name)) || frame.fields.find((field) => field.type === 'number');
  const out = [];
  for (let i = 0; i < frame.length; i++) {
    const row = { value: 0 };
    frame.fields.forEach((field) => {
      const value = field.values.get ? field.values.get(i) : field.values[i];
      if (field === valueField) {
        row.value = value;
      } else {
        row[field.name] = value;
      }
    });
    out.push(row);
  }
  return out;
};

const format = (seconds) => {
  if (seconds === undefined || seconds === null || isNaN(seconds)) {
    return '';
  }
  if (seconds < 60) {
    return (seconds < 10 ? seconds.toFixed(1) : Math.round(seconds)) + 's';
  }
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return minutes + 'm ' + Math.round(seconds % 60) + 's';
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 48) {
    return hours + 'h ' + (minutes % 60) + 'm';
  }
  return Math.floor(hours / 24) + 'd ' + (hours % 24) + 'h';
};

/** "3m ago" for a unix timestamp in seconds. */
const ago = (seconds) => {
  if (!seconds) {
    return '';
  }
  return format(Math.max(0, Date.now() / 1000 - seconds)) + ' ago';
};

const add = (parent, tag, className, text) => {
  const node = document.createElement(tag);
  if (className) {
    node.className = className;
  }
  if (text !== undefined) {
    node.textContent = text;
  }
  parent.appendChild(node);
  return node;
};

/** A link where the address is known, plain text where it is not. */
const link = (parent, className, text, href) => {
  const node = add(parent, href ? 'a' : 'span', className, text);
  if (href) {
    node.href = href;
    node.target = '_blank';
    node.rel = 'noreferrer';
  }
  return node;
};

/** The colored pill that names a run, the same on every panel. */
const keyChip = (parent, row, href) => {
  const chip = link(parent, 'pdx-key', nameOf(row), href);
  chip.style.background = colorOf(row.key || '');
  chip.title = row.key || '';
  return chip;
};

/** Remembers a choice per panel across the five-second refresh. */
const remember = (name, value) => {
  try {
    if (value === undefined) {
      return localStorage.getItem('pdx-' + name) || '';
    }
    localStorage.setItem('pdx-' + name, value);
  } catch (error) {
    return '';
  }
  return value;
};

const STAGES = {
  production: [
    'queued',
    'check',
    'code_review',
    'image',
    'renovate_queued',
    'renovate',
    'merge_request',
    'gitops_check',
    'merge_queued',
    'sync_queued',
    'sync',
    'rollout',
    'live',
  ],
  review: ['queued', 'check', 'code_review', 'image', 'sync_queued', 'sync', 'rollout', 'live'],
};
const FAILED = ['pipeline_failed', 'renovate_failed', 'gitops_failed', 'sync_failed', 'degraded'];
const kindOf = (row) => (row.kind === 'review' ? 'review' : 'production');
const lastOf = (row) => STAGES[kindOf(row)][STAGES[kindOf(row)].length - 1];
const isFailed = (row) => FAILED.indexOf(row.stage) !== -1;
const isDone = (row) => row.stage === lastOf(row);
const isClosed = (row) => row.stage === 'closed';
const isSettled = (row) => isDone(row) || isFailed(row) || isClosed(row);

/** A stage reads on screen under the name the pipeline and the tracker give it. */
const wordFor = (stage) => String(stage || '').replace(/_/g, ' ');

/**
 * Draws one card per run of the last seven days, in flight first.
 * A card carries the phases of the run, a chip per step, and a clock that keeps
 * counting between refreshes so the card moves with the event feed.
 */
const BUILD = {
  name: 'build',
  chips: [
    { label: 'queued', stages: ['queued'], link: 'pipeline_url' },
    { label: 'check', stages: ['check'], link: 'pipeline_url' },
    { label: 'code review', stages: ['code_review'], link: 'pipeline_url' },
    { label: 'image', stages: ['image'], link: 'pipeline_url' },
  ],
};
const DEPLOY = {
  name: 'deploy',
  chips: [
    { label: 'sync queued', stages: ['sync_queued'], link: 'argocd_url' },
    { label: 'sync', stages: ['sync'], link: 'argocd_url' },
    { label: 'rollout', stages: ['rollout'], link: 'argocd_url' },
  ],
};

/** Phases a run moves through, drawn left to right. */
const PHASES = {
  production: [
    BUILD,
    {
      name: 'renovate',
      chips: [
        { label: 'renovate queued', stages: ['renovate_queued'], link: 'renovate_url' },
        { label: 'renovate', stages: ['renovate'], link: 'renovate_url' },
      ],
    },
    {
      name: 'merge',
      chips: [
        { label: 'merge request', stages: ['merge_request'], link: 'mr_url' },
        { label: 'gitops check', stages: ['gitops_check'], link: 'mr_url' },
        { label: 'merge queued', stages: ['merge_queued'], link: 'mr_url' },
      ],
    },
    DEPLOY,
    { name: 'live', chips: [{ label: 'live', stages: ['live'], link: 'app_url' }] },
  ],
  review: [BUILD, DEPLOY, { name: 'live', chips: [{ label: 'live', stages: ['live'], link: 'app_url' }] }],
};

const MARKS = { done: '✓', failed: '✕', pending: '', running: '' };

/** Latest label set per run, the newest sample winning on the server side. */
const runs = new Map();
readRows('A').forEach((row) => {
  const held = runs.get(row.key);
  if (!held || row.value > held.value) {
    runs.set(row.key, row);
  }
});

/** Seconds keyed by run and stage, matching a row to its own label set. */
const keyed = (refId) => {
  const out = {};
  readRows(refId).forEach((row) => {
    out[row.key + '|' + row.stage] = row.value;
  });
  return out;
};
const elapsed = keyed('B');
const total = keyed('C');
const spent = keyed('D');

/** Address each service answers on, for the chip that closes a production run. */
const liveUrl = {};
readRows('E').forEach((row) => {
  if (row.url) {
    liveUrl[row.app] = row.url;
  }
});

/** When the tracker last reported each run. */
const seen = {};
readRows('F').forEach((row) => {
  seen[row.key] = Math.max(seen[row.key] || 0, row.value);
});

/** A run the tracker stopped reporting mid-flight, after a restart. */
const isStale = (row) => !isSettled(row) && elapsed[row.key + '|' + row.stage] === undefined;

const FILTERS = [
  ['all', 'All', () => true],
  ['flight', 'In flight', (row) => !isSettled(row) && !isStale(row)],
  ['production', 'Production', (row) => kindOf(row) === 'production'],
  ['review', 'Review', (row) => kindOf(row) === 'review'],
  ['failed', 'Failed', (row) => isFailed(row)],
];

const clocks = [];
const started = Date.now();
const tick = () => {
  const drifted = (Date.now() - started) / 1000;
  clocks.forEach((clock) => {
    clock.node.textContent = format(clock.base + drifted);
  });
};

/** When a run's current stage began, from its own clock. */
const sinceOf = (row) => Number(row.since) || seen[row.key] || 0;

const render = () => {
  clocks.length = 0;
  const chosen = remember('cards-filter') || 'all';
  const filter = (FILTERS.find((entry) => entry[0] === chosen) || FILTERS[0])[2];

  const root = document.createElement('div');
  root.className = 'pdx';

  const bar = add(root, 'div', 'pdx-bar');
  const buttons = add(bar, 'nav', 'pdx-buttons');
  FILTERS.forEach((entry) => {
    const button = add(buttons, 'button', entry[0] === chosen ? 'pdx-on' : '', entry[1]);
    button.onclick = () => {
      remember('cards-filter', entry[0]);
      render();
    };
  });

  const all = Array.from(runs.values());
  const rows = all.filter(filter).sort((left, right) => {
    const flight = (isSettled(left) || isStale(left) ? 1 : 0) - (isSettled(right) || isStale(right) ? 1 : 0);
    return flight || sinceOf(right) - sinceOf(left);
  });
  const inFlight = all.filter((row) => !isSettled(row) && !isStale(row)).length;
  add(bar, 'span', 'pdx-count', rows.length + ' of ' + all.length + ' runs in seven days, ' + inFlight + ' in flight');

  if (!rows.length) {
    add(root, 'div', 'pdx-empty', all.length ? 'No run matches this filter.' : 'Nothing deployed in the last seven days.');
  }

  rows.forEach((run) => {
    const kind = kindOf(run);
    const stages = STAGES[kind];
    const failed = isFailed(run);
    const done = isDone(run);
    const stale = isStale(run);
    const at = stages.indexOf(run.step || run.stage);
    const live = elapsed[run.key + '|' + run.stage];
    const app = run.app || '';
    const review = kind === 'review';
    const address = review ? run.url : liveUrl[app];

    const card = add(root, 'div', 'pdx-card' + (stale ? ' pdx-stale' : ''));
    card.style.borderLeftColor = colorOf(run.key || '');

    const head = add(card, 'div', 'pdx-head');
    keyChip(head, run, review ? run.mr_url : run.commit_url);
    link(head, 'pdx-app', app, run.project_url);
    if (review) {
      link(head, 'pdx-title', run.title || '', run.mr_url);
      link(head, 'pdx-version', run.sha, run.commit_url);
    } else {
      link(head, 'pdx-version', run.version || run.sha, run.commit_url);
    }
    link(head, 'pdx-meta', run.ref, run.ref_url);
    link(head, 'pdx-meta', run.author, run.author_url);
    if (failed) {
      add(head, 'span', 'pdx-badge pdx-bad', wordFor(run.stage));
    } else if (isClosed(run)) {
      add(head, 'span', 'pdx-badge pdx-dim', 'merge request closed ' + ago(sinceOf(run)));
    } else if (stale) {
      add(head, 'span', 'pdx-badge pdx-warn', 'no report for ' + ago(seen[run.key]).replace(' ago', ''));
    } else if (done) {
      add(head, 'span', 'pdx-badge pdx-ok', wordFor(run.stage) + ' ' + ago(sinceOf(run)));
    }
    add(head, 'span', 'pdx-spacer');

    const clock = add(head, 'span', 'pdx-total');
    const elapsedTotal = total[run.key + '|' + run.stage];
    clock.textContent = format(elapsedTotal);
    if (!done && !failed && !stale && elapsedTotal !== undefined) {
      clocks.push({ node: clock, base: elapsedTotal });
    }

    const links = add(head, 'nav', 'pdx-buttons');
    [
      ['Pipeline', run.pipeline_url],
      ['Merge request', run.mr_url],
      ['Argo CD', run.argocd_url],
      ['Open', address],
    ].forEach((pair) => {
      if (pair[1]) {
        link(links, '', pair[0], pair[1]);
      }
    });

    const flow = add(card, 'div', 'pdx-flow');
    PHASES[kind].forEach((phase, index) => {
      if (index) {
        add(flow, 'div', 'pdx-join');
      }
      const box = add(flow, 'div', 'pdx-phase');
      add(box, 'div', 'pdx-phase-name', phase.name);
      const chips = add(box, 'div', 'pdx-chips');

      phase.chips.forEach((chip) => {
        const indexes = chip.stages.map((stage) => stages.indexOf(stage));
        const first = Math.min.apply(null, indexes);
        const last = Math.max.apply(null, indexes);

        let state = 'pending';
        if (done || at > last) {
          state = 'done';
        } else if (at >= first && at <= last) {
          state = failed ? 'failed' : 'running';
        } else if (at === -1 && chip.stages.some((stage) => spent[run.key + '|' + stage] !== undefined)) {
          state = 'done';
        }

        const target = chip.link === 'app_url' ? address : run[chip.link];
        const node = link(chips, 'pdx-chip pdx-' + state, undefined, target);
        add(node, 'span', 'pdx-mark', MARKS[state]);
        add(node, 'span', 'pdx-chip-label', chip.label);

        let seconds = 0;
        let counting = false;
        chip.stages.forEach((stage) => {
          if (spent[run.key + '|' + stage] !== undefined) {
            seconds += spent[run.key + '|' + stage];
          } else if (stage === run.stage && live !== undefined) {
            seconds += live;
            counting = true;
          }
        });

        if (state !== 'pending' && seconds > 0) {
          const time = add(node, 'span', 'pdx-chip-time', format(seconds));
          if (counting && state === 'running' && !stale) {
            clocks.push({ node: time, base: seconds });
          }
        }
      });
    });
  });

  paint(root);
};

render();
const timer = setInterval(tick, 250);
return () => clearInterval(timer);

options.styles:
.pdx {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 2px;
  font-size: 12px;
  height: 100%;
  overflow-y: auto;
}

.pdx a {
  color: inherit;
}

.pdx-empty {
  color: var(--pdx-dim);
  padding: 16px 4px;
}

.pdx-key {
  display: inline-flex;
  align-items: center;
  border-radius: 10px;
  padding: 0 8px;
  font-family: var(--pdx-mono);
  font-size: 11px;
  line-height: 18px;
  white-space: nowrap;
  color: #fff;
  font-weight: 600;
  text-shadow: 0 0 2px rgba(0, 0, 0, 0.5);
}

.pdx-dim {
  color: var(--pdx-dim);
}

.pdx-mono {
  font-family: var(--pdx-mono);
}

.pdx-buttons {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.pdx-buttons a,
.pdx-buttons button {
  border: 1px solid var(--pdx-border);
  border-radius: 3px;
  padding: 1px 7px;
  color: var(--pdx-dim);
  background: transparent;
  font: inherit;
  cursor: pointer;
  white-space: nowrap;
}

.pdx-buttons a:hover,
.pdx-buttons button:hover {
  color: var(--pdx-link);
  border-color: var(--pdx-link);
}

.pdx-buttons .pdx-on {
  color: var(--pdx-text);
  border-color: var(--pdx-text);
}

.pdx-badge {
  border: 1px solid currentColor;
  border-radius: 3px;
  padding: 0 5px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pdx-ok {
  color: var(--pdx-ok);
}

.pdx-bad {
  color: var(--pdx-bad);
}

.pdx-run {
  color: var(--pdx-run);
}

.pdx-warn {
  color: var(--pdx-warn);
}

.pdx-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.pdx-count {
  color: var(--pdx-dim);
  margin-left: auto;
}

.pdx-card {
  border: 1px solid var(--pdx-border);
  border-left: 4px solid var(--pdx-accent);
  border-radius: 4px;
  background: var(--pdx-panel);
  padding: 7px 9px 8px;
}

.pdx-stale {
  opacity: 0.6;
}

.pdx-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 6px;
}

.pdx-app {
  font-size: 14px;
  font-weight: 600;
}

.pdx-version {
  font-family: var(--pdx-mono);
  color: var(--pdx-dim);
}

.pdx-meta {
  color: var(--pdx-dim);
}

.pdx-title {
  color: var(--pdx-text);
}

.pdx-spacer {
  flex: 1;
}

.pdx-total {
  font-variant-numeric: tabular-nums;
  color: var(--pdx-text);
}

.pdx-flow {
  display: flex;
  align-items: stretch;
  overflow-x: auto;
  padding-bottom: 2px;
}

.pdx-phase {
  border: 1px solid var(--pdx-border);
  border-radius: 4px;
  background: var(--pdx-phase);
  padding: 5px;
  min-width: 118px;
}

.pdx-phase-name {
  font-weight: 600;
  color: var(--pdx-dim);
  text-transform: lowercase;
  margin: 0 2px 6px;
}

.pdx-chips {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.pdx-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--pdx-border);
  border-radius: 14px;
  background: var(--pdx-chip);
  padding: 2px 9px 2px 5px;
  color: var(--pdx-text);
}

.pdx-chip:hover {
  border-color: var(--pdx-link);
}

.pdx-chip-label {
  flex: 1;
  white-space: nowrap;
}

.pdx-chip-time {
  font-variant-numeric: tabular-nums;
  color: var(--pdx-dim);
  font-size: 11px;
}

.pdx-pending {
  opacity: 0.45;
}

.pdx-mark {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  line-height: 1;
}

.pdx-done .pdx-mark {
  color: var(--pdx-ok);
}

.pdx-failed .pdx-mark {
  color: var(--pdx-bad);
}

.pdx-pending .pdx-mark {
  color: var(--pdx-dim);
}

.pdx-running .pdx-mark {
  color: var(--pdx-run);
  border-style: solid;
  border-top-color: transparent;
  animation: pdx-turn 0.9s linear infinite;
}

.pdx-stale .pdx-running .pdx-mark {
  animation: none;
  border-top-color: currentColor;
  color: var(--pdx-warn);
}

.pdx-running .pdx-chip-label {
  color: var(--pdx-run);
}

.pdx-join {
  width: 16px;
  height: 2px;
  flex: 0 0 16px;
  align-self: center;
  background: var(--pdx-accent);
}

@keyframes pdx-turn {
  to {
    transform: rotate(360deg);
  }
}

options.afterRender:
const element = context.element;
const theme = context.grafana.theme;

/** Colors follow the dashboard theme, so every panel reads in light and dark. */
const palette = {
  '--pdx-text': theme.colors.text.primary,
  '--pdx-dim': theme.colors.text.secondary,
  '--pdx-link': theme.colors.text.link,
  '--pdx-border': theme.colors.border.weak,
  '--pdx-panel': theme.colors.background.primary,
  '--pdx-phase': theme.colors.background.secondary,
  '--pdx-chip': theme.colors.background.primary,
  '--pdx-ok': theme.colors.success.text,
  '--pdx-bad': theme.colors.error.text,
  '--pdx-warn': theme.colors.warning.text,
  '--pdx-run': theme.colors.primary.text,
  '--pdx-accent': theme.colors.border.strong,
  '--pdx-mono': theme.typography.fontFamilyMonospace,
};
Object.keys(palette).forEach((key) => element.style.setProperty(key, palette[key]));

/**
 * The plugin renders `element` itself and keeps track of what it put there,
 * so replacing those children leaves it patching nodes that are gone and the next
 * refresh throws. `.pdx-mount` comes from the panel's content empty, which leaves
 * the plugin nothing to track inside it.
 */
const mountOf = () => element.querySelector('.pdx-mount') || element;

/** Box the panel scrolls in, walking out from the drawing. null while nothing scrolls. */
const scrollerOf = (node) => {
  for (let box = node; box; box = box.parentElement) {
    if (box.scrollHeight > box.clientHeight + 1 && /auto|scroll/.test(getComputedStyle(box).overflowY)) {
      return box;
    }
  }
  return null;
};

/** Swaps a fresh drawing in, holding the reader's scroll position across the refresh. */
const paint = (root) => {
  const mount = mountOf();
  const scroller = scrollerOf(mount);
  const top = scroller ? scroller.scrollTop : 0;
  mount.replaceChildren(root);
