/**
 * One color per run, the same on every panel. The key hashes onto a ring of
 * hues, so a merge request keeps its color across pushes and refreshes.
 */
const HUES = [212, 28, 142, 282, 48, 322, 182, 2, 102, 242, 62, 342];
const hueOf = (key) => {
  let hash = 7;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  return HUES[hash % HUES.length];
};
const colorOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 38 : 42) + '%)';
const tintOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 55 : 45) + '% / 0.14)';

/** Short name of a run: the merge request number for a review, the commit for production. */
const nameOf = (row) => {
  const key = row.key || '';
  if (row.kind === 'review' || key.indexOf('!') !== -1) {
    return '!' + (row.iid || key.split('!')[1] || '');
  }
  return row.sha || key;
};

/** Frames arrive one per query. Reading them by refId keeps order out of it. */
const frames = {};
((context.panelData && context.panelData.series) || []).forEach((frame) => {
  frames[frame.refId] = frame;
});

/** Rows of a frame as plain objects, the sample value under `value`. */
const readRows = (refId) => {
  const frame = frames[refId];
  if (!frame || !frame.fields || !frame.length) {
    return [];
  }
  const valueField = frame.fields.find((field) => field.type === 'number' && /^Value/.test(field.name)) || frame.fields.find((field) => field.type === 'number');
