  .sort((left, right) => left.row.app.localeCompare(right.row.app))
  .forEach((tile) => {
    const box = add(production, 'div', 'pdx-tile');
    const head = add(box, 'div', 'pdx-tile-head');
    link(head, 'pdx-tile-name', tile.row.app, tile.row.url);
    const newest = Math.min.apply(null, tile.workloads.map((row) => age[row.id] || Infinity));
    if (isFinite(newest)) {
      add(head, 'span', 'pdx-dim', 'rolled out ' + format(newest) + ' ago');
    }
    tile.workloads
      .sort((left, right) => left.workload.localeCompare(right.workload))
      .forEach((row) => {
        const line = add(box, 'div', 'pdx-tile-row');
        add(line, 'span', dotFor(row.value, desired[row.id]));
