      ['Open', tile.row.url],
      ['Argo CD', tile.row.argocd_url],
      ['Project', tile.row.project_url],
    ].forEach((pair) => {
      if (pair[1]) {
        link(buttons, '', pair[0], pair[1]);
      }
    });
  });

