  add(root, 'div', 'pdx-empty', 'The tracker has not reported the fleet yet.');
}

/** Review environments, one tile per merge request, in its color. */
const reviews = readRows('D').filter((row) => !isClosed(row)).sort((left, right) => Number(right.iid || 0) - Number(left.iid || 0));
add(root, 'div', 'pdx-section', 'review environments');
if (!reviews.length) {
  add(root, 'div', 'pdx-empty', 'No merge request has an environment right now.');
}
const grid = add(root, 'div', 'pdx-tiles');
reviews.forEach((row) => {
  const box = add(grid, 'div', 'pdx-tile');
  box.style.borderTopColor = colorOf(row.key || '');
  box.style.background = tintOf(row.key || '');
  const head = add(box, 'div', 'pdx-tile-head');
  keyChip(head, row, row.mr_url);
  link(head, 'pdx-tile-name', row.title || row.app, row.mr_url);
  const line = add(box, 'div', 'pdx-tile-row');
  const state = isFailed(row) ? 'pdx-dot pdx-dot-bad' : isDone(row) ? 'pdx-dot pdx-dot-ok' : 'pdx-dot pdx-dot-warn';
  add(line, 'span', state);
  add(line, 'span', isFailed(row) ? 'pdx-bad' : '', wordFor(row.stage));
  link(line, 'pdx-mono pdx-tile-fill', row.sha || '', row.commit_url);
  link(line, '', row.ref || '', row.ref_url);
  link(line, '', row.author || '', row.author_url);
  const buttons = add(box, 'nav', 'pdx-buttons');
  [
    ['Open', row.url],
    ['Merge request', row.mr_url],
    ['Pipeline', row.pipeline_url],
    ['Argo CD', row.argocd_url],
  ].forEach((pair) => {
    if (pair[1]) {
      link(buttons, '', pair[0], pair[1]);
    }
  });
});

paint(root);

