const scrollerOf = (node) => {
  for (let box = node; box; box = box.parentElement) {
    if (box.scrollHeight > box.clientHeight + 1 && /auto|scroll/.test(getComputedStyle(box).overflowY)) {
      return box;
    }
  }
  return null;
};

/** Swaps a fresh drawing in, holding the reader's scroll position across the refresh. */
const paint = (root) => {
  const mount = mountOf();
  const scroller = scrollerOf(mount);
  const top = scroller ? scroller.scrollTop : 0;
  mount.replaceChildren(root);
  if (scroller && scroller.scrollTop !== top) {
    scroller.scrollTop = top;
  }
