const hueOf = (key) => {
  let hash = 7;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  return HUES[hash % HUES.length];
};
const colorOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 38 : 42) + '%)';
const tintOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 55 : 45) + '% / 0.14)';

