  production: [
    'queued',
    'check',
    'code_review',
    'image',
    'renovate_queued',
    'renovate',
    'merge_request',
    'gitops_check',
    'merge_queued',
    'sync_queued',
    'sync',
    'rollout',
    'live',
  ],
  review: ['queued', 'check', 'code_review', 'image', 'sync_queued', 'sync', 'rollout', 'live'],
};
const FAILED = ['pipeline_failed', 'renovate_failed', 'gitops_failed', 'sync_failed', 'degraded'];
const kindOf = (row) => (row.kind === 'review' ? 'review' : 'production');
const lastOf = (row) => STAGES[kindOf(row)][STAGES[kindOf(row)].length - 1];
const isFailed = (row) => FAILED.indexOf(row.stage) !== -1;
const isDone = (row) => row.stage === lastOf(row);
const isClosed = (row) => row.stage === 'closed';
const isSettled = (row) => isDone(row) || isFailed(row) || isClosed(row);

/** A stage reads on screen under the name the pipeline and the tracker give it. */
const wordFor = (stage) => String(stage || '').replace(/_/g, ' ');

/**
 * One bar per run, its stages laid end to end, all bars on one scale.
 * The run's chip carries its color; the segments carry the stage's.
 */
const STAGE_HUES = {
  queued: 0,
  check: 25,
  code_review: 45,
  image: 62,
  renovate_queued: 262,
  renovate: 282,
  merge_request: 318,
  gitops_check: 334,
  merge_queued: 350,
  sync_queued: 180,
  sync: 205,
  rollout: 130,
};
const stageColor = (stage) => {
  const hue = STAGE_HUES[stage] === undefined ? 0 : STAGE_HUES[stage];
  const sat = stage === 'queued' ? 0 : 55;
  return 'hsl(' + hue + ' ' + sat + '% ' + (theme.isDark ? 55 : 50) + '%)';
};

const latest = new Map();
readRows('B').forEach((row) => {
  const held = latest.get(row.key);
  if (!held || row.value > held.value) {
    latest.set(row.key, row);
  }
});
const seen = {};
readRows('C').forEach((row) => {
  seen[row.key] = Math.max(seen[row.key] || 0, row.value);
});

const bars = new Map();
readRows('A').forEach((row) => {
  const bar = bars.get(row.key) || { key: row.key, kind: row.kind, app: row.app, sha: row.sha, stages: {}, total: 0 };
  bar.stages[row.stage] = row.value;
  bar.total += row.value;
  bars.set(row.key, bar);
});

const sinceOf = (key) => Number((latest.get(key) || {}).since) || seen[key] || 0;
const rows = Array.from(bars.values()).sort((left, right) => sinceOf(right.key) - sinceOf(left.key));
const widest = Math.max.apply(null, rows.map((bar) => bar.total).concat([1]));

const root = document.createElement('div');
root.className = 'pdx';

const legend = add(root, 'div', 'pdx-legend');
Object.keys(STAGE_HUES).forEach((stage) => {
  const item = add(legend, 'span', '');
  const swatch = add(item, 'span', 'pdx-swatch');
  swatch.style.background = stageColor(stage);
  add(item, 'span', '', wordFor(stage));
});

if (!rows.length) {
  add(root, 'div', 'pdx-empty', 'No run has finished a step in the last seven days.');
}

rows.forEach((bar) => {
  const run = latest.get(bar.key) || { key: bar.key, kind: bar.kind, app: bar.app, sha: bar.sha };
  const line = add(root, 'div', 'pdx-line');
  keyChip(line, run, kindOf(run) === 'review' ? run.mr_url : run.commit_url);
  const who = add(line, 'div', 'pdx-line-who');
  who.textContent = (run.app || bar.app || '') + ' ' + (kindOf(run) === 'review' ? run.title || '' : run.version || bar.sha || '');
  who.title = who.textContent;
  const track = add(line, 'div', 'pdx-track');
  STAGES[kindOf(run)].forEach((stage) => {
    const seconds = bar.stages[stage];
    if (!seconds) {
      return;
    }
    const seg = add(track, 'div', 'pdx-seg' + (isFailed(run) && run.step === stage ? ' pdx-seg-failed' : ''));
    seg.style.width = (100 * seconds) / widest + '%';
    seg.style.background = stageColor(stage);
    seg.title = wordFor(stage) + ': ' + format(seconds);
  });
  const total = add(line, 'div', 'pdx-line-total', format(bar.total));
  if (isFailed(run)) {
    total.className += ' pdx-bad';
    total.title = wordFor(run.stage);
  }
});

paint(root);

