  padding: 16px 4px;
}

.pdx-key {
  display: inline-flex;
  align-items: center;
  border-radius: 10px;
  padding: 0 8px;
  font-family: var(--pdx-mono);
  font-size: 11px;
  line-height: 18px;
  white-space: nowrap;
  color: #fff;
  font-weight: 600;
  text-shadow: 0 0 2px rgba(0, 0, 0, 0.5);
}

.pdx-dim {
  color: var(--pdx-dim);
}

.pdx-mono {
  font-family: var(--pdx-mono);
}

.pdx-buttons {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.pdx-buttons a,
.pdx-buttons button {
  border: 1px solid var(--pdx-border);
  border-radius: 3px;
  padding: 1px 7px;
  color: var(--pdx-dim);
  background: transparent;
  font: inherit;
  cursor: pointer;
  white-space: nowrap;
}

.pdx-buttons a:hover,
.pdx-buttons button:hover {
  color: var(--pdx-link);
  border-color: var(--pdx-link);
}

.pdx-buttons .pdx-on {
  color: var(--pdx-text);
  border-color: var(--pdx-text);
}

.pdx-badge {
  border: 1px solid currentColor;
  border-radius: 3px;
  padding: 0 5px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pdx-ok {
  color: var(--pdx-ok);
}

.pdx-bad {
  color: var(--pdx-bad);
}

.pdx-run {
  color: var(--pdx-run);
}

.pdx-warn {
  color: var(--pdx-warn);
}

.pdx-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  color: var(--pdx-dim);
  padding: 0 2px;
}

.pdx-swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
  margin-right: 5px;
  vertical-align: -1px;
}

.pdx-line {
  display: grid;
  grid-template-columns: 70px 200px 1fr 70px;
  align-items: center;
  gap: 8px;
}

.pdx-line-who {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--pdx-dim);
}

.pdx-track {
  display: flex;
  height: 16px;
  border-radius: 3px;
  overflow: hidden;
  background: var(--pdx-phase);
}

.pdx-seg {
  height: 100%;
  min-width: 2px;
}

.pdx-seg-failed {
  outline: 2px solid var(--pdx-bad);
  outline-offset: -2px;
}

.pdx-line-total {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

options.afterRender:
const element = context.element;
const theme = context.grafana.theme;

/** Colors follow the dashboard theme, so every panel reads in light and dark. */
const palette = {
  '--pdx-text': theme.colors.text.primary,
  '--pdx-dim': theme.colors.text.secondary,
  '--pdx-link': theme.colors.text.link,
  '--pdx-border': theme.colors.border.weak,
  '--pdx-panel': theme.colors.background.primary,
  '--pdx-phase': theme.colors.background.secondary,
  '--pdx-chip': theme.colors.background.primary,
  '--pdx-ok': theme.colors.success.text,
  '--pdx-bad': theme.colors.error.text,
  '--pdx-warn': theme.colors.warning.text,
  '--pdx-run': theme.colors.primary.text,
  '--pdx-accent': theme.colors.border.strong,
  '--pdx-mono': theme.typography.fontFamilyMonospace,
};
Object.keys(palette).forEach((key) => element.style.setProperty(key, palette[key]));

/**
 * The plugin renders `element` itself and keeps track of what it put there,
 * so replacing those children leaves it patching nodes that are gone and the next
 * refresh throws. `.pdx-mount` comes from the panel's content empty, which leaves
 * the plugin nothing to track inside it.
 */
const mountOf = () => element.querySelector('.pdx-mount') || element;

/** Box the panel scrolls in, walking out from the drawing. null while nothing scrolls. */
const scrollerOf = (node) => {
  for (let box = node; box; box = box.parentElement) {
    if (box.scrollHeight > box.clientHeight + 1 && /auto|scroll/.test(getComputedStyle(box).overflowY)) {
      return box;
    }
  }
  return null;
};

/** Swaps a fresh drawing in, holding the reader's scroll position across the refresh. */
const paint = (root) => {
  const mount = mountOf();
  const scroller = scrollerOf(mount);
  const top = scroller ? scroller.scrollTop : 0;
  mount.replaceChildren(root);
  if (scroller && scroller.scrollTop !== top) {
    scroller.scrollTop = top;
  }
};

/**
 * One color per run, the same on every panel. The key hashes onto a ring of
 * hues, so a merge request keeps its color across pushes and refreshes.
 */
const HUES = [212, 28, 142, 282, 48, 322, 182, 2, 102, 242, 62, 342];
const hueOf = (key) => {
  let hash = 7;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  return HUES[hash % HUES.length];
};
const colorOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 38 : 42) + '%)';
const tintOf = (key) => 'hsl(' + hueOf(key) + ' 60% ' + (theme.isDark ? 55 : 45) + '% / 0.14)';

/** Short name of a run: the merge request number for a review, the commit for production. */
const nameOf = (row) => {
  const key = row.key || '';
  if (row.kind === 'review' || key.indexOf('!') !== -1) {
    return '!' + (row.iid || key.split('!')[1] || '');
  }
  return row.sha || key;
};

/** Frames arrive one per query. Reading them by refId keeps order out of it. */
const frames = {};
((context.panelData && context.panelData.series) || []).forEach((frame) => {
  frames[frame.refId] = frame;
});

/** Rows of a frame as plain objects, the sample value under `value`. */
const readRows = (refId) => {
  const frame = frames[refId];
  if (!frame || !frame.fields || !frame.length) {
    return [];
  }
  const valueField = frame.fields.find((field) => field.type === 'number' && /^Value/.test(field.name)) || frame.fields.find((field) => field.type === 'number');
  const out = [];
  for (let i = 0; i < frame.length; i++) {
    const row = { value: 0 };
    frame.fields.forEach((field) => {
      const value = field.values.get ? field.values.get(i) : field.values[i];
      if (field === valueField) {
        row.value = value;
      } else {
        row[field.name] = value;
      }
    });
    out.push(row);
  }
  return out;
};

const format = (seconds) => {
  if (seconds === undefined || seconds === null || isNaN(seconds)) {
    return '';
  }
  if (seconds < 60) {
    return (seconds < 10 ? seconds.toFixed(1) : Math.round(seconds)) + 's';
  }
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return minutes + 'm ' + Math.round(seconds % 60) + 's';
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 48) {
    return hours + 'h ' + (minutes % 60) + 'm';
  }
  return Math.floor(hours / 24) + 'd ' + (hours % 24) + 'h';
};

/** "3m ago" for a unix timestamp in seconds. */
const ago = (seconds) => {
  if (!seconds) {
    return '';
  }
  return format(Math.max(0, Date.now() / 1000 - seconds)) + ' ago';
};

const add = (parent, tag, className, text) => {
  const node = document.createElement(tag);
  if (className) {
    node.className = className;
  }
  if (text !== undefined) {
    node.textContent = text;
  }
  parent.appendChild(node);
  return node;
};

/** A link where the address is known, plain text where it is not. */
const link = (parent, className, text, href) => {
  const node = add(parent, href ? 'a' : 'span', className, text);
  if (href) {
    node.href = href;
    node.target = '_blank';
    node.rel = 'noreferrer';
  }
  return node;
};

/** The colored pill that names a run, the same on every panel. */
const keyChip = (parent, row, href) => {
  const chip = link(parent, 'pdx-key', nameOf(row), href);
  chip.style.background = colorOf(row.key || '');
  chip.title = row.key || '';
  return chip;
};

/** Remembers a choice per panel across the five-second refresh. */
const remember = (name, value) => {
  try {
    if (value === undefined) {
      return localStorage.getItem('pdx-' + name) || '';
    }
    localStorage.setItem('pdx-' + name, value);
  } catch (error) {
    return '';
  }
  return value;
};

const STAGES = {
  production: [
    'queued',
    'check',
    'code_review',
    'image',
    'renovate_queued',
    'renovate',
    'merge_request',
    'gitops_check',
    'merge_queued',
    'sync_queued',
    'sync',
    'rollout',
    'live',
  ],
  review: ['queued', 'check', 'code_review', 'image', 'sync_queued', 'sync', 'rollout', 'live'],
};
const FAILED = ['pipeline_failed', 'renovate_failed', 'gitops_failed', 'sync_failed', 'degraded'];
const kindOf = (row) => (row.kind === 'review' ? 'review' : 'production');
const lastOf = (row) => STAGES[kindOf(row)][STAGES[kindOf(row)].length - 1];
const isFailed = (row) => FAILED.indexOf(row.stage) !== -1;
const isDone = (row) => row.stage === lastOf(row);
const isClosed = (row) => row.stage === 'closed';
const isSettled = (row) => isDone(row) || isFailed(row) || isClosed(row);

/** A stage reads on screen under the name the pipeline and the tracker give it. */
const wordFor = (stage) => String(stage || '').replace(/_/g, ' ');

/**
 * The tracker's log as sentences, newest first, each line in its run's color.
 * Clicking a run's chip keeps that run alone; the button at the top lets go.
 */
const frame = frames['A'];
const events = [];
if (frame && frame.fields) {
  const timeField = frame.fields.find((field) => field.type === 'time') || frame.fields[0];
  const lineField = frame.fields.find((field) => field.name === 'Line' || field.name === '_msg' || field.name === 'line' || field.name === 'body') || frame.fields.find((field) => field.type === 'string');
  for (let i = 0; i < frame.length; i++) {
    const raw = lineField.values.get ? lineField.values.get(i) : lineField.values[i];
    const when = timeField.values.get ? timeField.values.get(i) : timeField.values[i];
    let entry;
    try {
      entry = JSON.parse(raw);
    } catch (error) {
      entry = { event: 'line', text: String(raw) };
    }
    entry.when = typeof when === 'number' ? when : Date.parse(when);
    events.push(entry);
  }
}
events.sort((left, right) => right.when - left.when);

/** What a line says, in words. */
const sentence = (entry) => {
  switch (entry.event) {
    case 'stage':
      return { text: wordFor(entry.from), to: wordFor(entry.to), tail: entry.seconds !== undefined ? 'after ' + format(entry.seconds) : '' };
    case 'production.new':
      return { text: 'pipeline started on ' + (entry.ref || '') };
    case 'production.finished':
      return { text: 'live in production after ' + format(entry.seconds) };
    case 'review.begin':
      return { text: 'new head commit ' + (entry.sha || '') };
    case 'review.adopted':
      return { text: 'environment found running on ' + (entry.sha || '') };
    case 'review.closed':
      return { text: 'merge request ' + (entry.state || 'closed') + ', environment removed' };
    case 'review.kicked':
      return { text: 'replaced pod ' + (entry.pod || '') + ' waiting on the image' };
    case 'review.gone':
      return { text: 'environment gone from the cluster' };
    case 'retry':
      return { text: 'pipeline retried, back at ' + wordFor(entry.step) };
    case 'start':
      return { text: 'tracker started' };
    case 'errand.failed':
    case 'push.failed':
    case 'fleet.failed':
    case 'cluster.failed':
      return { text: entry.event.replace('.failed', '') + ' call failed: ' + (entry.error || ''), bad: true };
    default:
      return { text: entry.text || entry.event || '' };
  }
};

const render = () => {
  const only = remember('feed-only');
  const root = document.createElement('div');
  root.className = 'pdx';

  const bar = add(root, 'div', 'pdx-bar');
  const buttons = add(bar, 'nav', 'pdx-buttons');
  const all = add(buttons, 'button', only ? '' : 'pdx-on', only ? 'Show every run' : 'Every run');
  all.onclick = () => {
    remember('feed-only', '');
    render();
  };
  if (only) {
    add(bar, 'span', 'pdx-dim', 'showing ' + only);
  }

  const shown = events.filter((entry) => !only || entry.key === only);
  if (!shown.length) {
    add(root, 'div', 'pdx-empty', events.length ? 'No line for this run in the time range.' : 'No events in the time range.');
  }
  shown.forEach((entry) => {
    const line = add(root, 'div', 'pdx-event');
    const when = new Date(entry.when);
    add(line, 'span', 'pdx-when', isNaN(when) ? '' : when.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    const who = add(line, 'span', '');
    if (entry.key) {
      const chip = keyChip(who, { key: entry.key, kind: entry.kind, iid: entry.iid, sha: entry.sha });
      chip.style.cursor = 'pointer';
      chip.onclick = () => {
        remember('feed-only', entry.key);
        render();
      };
    }
    const said = sentence(entry);
    const what = add(line, 'span', 'pdx-what' + (said.bad ? ' pdx-bad' : ''));
    if (entry.app && entry.event !== 'start') {
      add(what, 'span', 'pdx-dim', entry.app + ' ');
    }
    add(what, 'span', '', said.text);
    if (said.to) {
      add(what, 'span', 'pdx-arrow', '→');
      add(what, 'span', '', said.to);
    }
    if (said.tail) {
      add(what, 'span', 'pdx-dim', ' ' + said.tail);
    }
  });

  paint(root);
};

render();

